insert into public.menu_categories(name,sort_order) values('Snacks',1),('Quick Bites',2),('Meals',3),('Drinks',4) on conflict(name) do nothing;
insert into public.menu_items(id,name,description,category,price_paise,image_url,stock,is_available) values
('samosa','Punjabi Samosa','Crispy pastry with spiced potato filling','Snacks',2000,'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=800&q=80',30,true),('chai','Masala Chai','Fresh ginger and cardamom tea','Drinks',1500,'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?auto=format&fit=crop&w=800&q=80',50,true),('sandwich','Garden Sandwich','Toasted vegetables and mint chutney','Quick Bites',5500,'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=800&q=80',20,true),('maggi','Masala Maggi','Classic campus-style masala noodles','Quick Bites',4000,'https://images.unsplash.com/photo-1612929633738-8fe44f7ec841?auto=format&fit=crop&w=800&q=80',25,true),('momos','Steamed Momos','Soft dumplings with spicy red chutney','Snacks',6500,'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80',18,true),('coffee','Iced Cold Coffee','Creamy chilled coffee','Drinks',6000,'https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=800&q=80',20,true),('roll','Paneer Tikka Roll','Smoky paneer, onion and green chutney','Meals',9000,'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=800&q=80',15,true),('thali','Homestyle Veg Thali','Dal, seasonal sabzi, rice, roti and salad','Meals',12000,'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=800&q=80',12,true) on conflict(id) do update set name=excluded.name,description=excluded.description,category=excluded.category,price_paise=excluded.price_paise,image_url=excluded.image_url,stock=excluded.stock,is_available=excluded.is_available;
insert into public.pickup_slots(label,starts_at,ends_at,capacity) select label,starts_at,ends_at,20 from(values('12:30 PM – 12:45 PM',date_trunc('day',now())+interval '1 day 12 hours 30 minutes',date_trunc('day',now())+interval '1 day 12 hours 45 minutes'),('12:45 PM – 1:00 PM',date_trunc('day',now())+interval '1 day 12 hours 45 minutes',date_trunc('day',now())+interval '1 day 13 hours'),('1:00 PM – 1:15 PM',date_trunc('day',now())+interval '1 day 13 hours',date_trunc('day',now())+interval '1 day 13 hours 15 minutes'),('1:15 PM – 1:30 PM',date_trunc('day',now())+interval '1 day 13 hours 15 minutes',date_trunc('day',now())+interval '1 day 13 hours 30 minutes')) s(label,starts_at,ends_at) where not exists(select 1 from public.pickup_slots);
